static inline unsigned short str2s(const char* s, unsigned int len, int *err) /* <=== str2s */ 
{
	unsigned short ret;
	int i;
	unsigned char *limit;
	unsigned char* str;

	/*init*/
	str=(unsigned char*)s;
	ret=i=0;
	limit=str+len;

	for(;str<limit ;str++){
		if ( (*str <= '9' ) && (*str >= '0') ){
				ret=ret*10+*str-'0';
				i++;
				if (i>5) goto error_digits;
		}else{
				/* error unknown char */
				goto error_char;
		}
	}
	if (err) *err=0;
	return ret;

error_digits:
	if (err) *err=1;
	return 0;
error_char:
	if (err) *err=1;
	return 0;
}

